raw = ['1250', '980.5', '', 'NA', '1100', 'abc']
values, missing = [], 0
for item in raw:
    try:
        values.append(float(item))
    except ValueError:
        missing += 1

print(values)                  # [1250.0, 980.5, 1100.0]
print(missing)                 # 3
print(round(sum(values) / len(values), 2))  # 1110.17
